import React, { useState } from 'react';

const TodoList = () => {
  const initialTasks = JSON.parse(localStorage.getItem('todoTasks'));
  const [taskList, setTaskList] = useState(initialTasks);

  const addTask = (itemName, qty) => {
    if (!itemName.trim() || qty <= 0) return;
    const newTask = {
      id: Date.now(),
      itemName,
      qty: Number(qty),
    };
    const updatedTasks = [...taskList, newTask];
    setTaskList(updatedTasks);
    localStorage.setItem('todoTasks', JSON.stringify(updatedTasks));
  };

  const deleteTask = (id) => {
    const updatedTasks = taskList.filter((item) => item.id !== id);
    setTaskList(updatedTasks);
    localStorage.setItem('todoTasks', JSON.stringify(updatedTasks));
  };

  return (
    <div>
      <Form addTask={addTask} taskList={taskList} deleteTask={deleteTask} />
    </div>
  );
};

export default TodoList;

function Form({ addTask, taskList, deleteTask }) {
  const [itemName, setItemName] = useState('');
  const [qty, setQty] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    addTask(itemName, qty);
    setItemName('');
    setQty('');
  };

  return (
    <div>
      <form
        className='container mt-5 p-3 border border-2 rounded bg-info-subtle'
        onSubmit={handleSubmit}
      >
        <section className="mb-3 mt-2">
          <h2 className="text-center text-dark">
            <span className='badge bg-dark m-3'>Things To Bring</span>
          </h2>
          <input
            type="text"
            className="form-control"
            placeholder='Enter Item Name'
            value={itemName}
            onChange={(e) => setItemName(e.target.value)}
          />
          <input
            type="number"
            className="form-control mt-2"
            placeholder='Quantity'
            value={qty}
            onChange={(e) => setQty(e.target.value)}
          />
        </section>
        <input type='submit' className="btn btn-sm btn-dark text-white" />
        <TaskList taskList={taskList} deleteTask={deleteTask} />
      </form>
    </div>
  );
}

function TaskList({ taskList, deleteTask }) {
  if (taskList.length === 0) {
    return <h4 className='text-center mt-3 text-danger'>Your cart is empty</h4>;
  }
  return (
    <ul className='list-group mt-3'>
      {taskList.map((item) => (
        <Task key={item.id} item={item} deleteTask={deleteTask} />
      ))}
    </ul>
  );
}

function Task({ item, deleteTask }) {
  const { itemName, qty, id } = item;
  return (
    <li className='list-group-item d-flex justify-content-between align-items-center'>
      <span className='text-monospace fs-5'>
        {itemName}
        <span className='badge bg-primary rounded-pill ms-2'>{qty}</span>
      </span>
      <button
        className='btn btn-danger btn-sm'
        onClick={() => deleteTask(id)}
      >
        Delete
      </button>
    </li>
  );
}
